let enabled = false;
const userGems = new Map<string, BoostGem>();
export function setBoostGemsEnabled(value: boolean) {
  enabled = value;
  if (!value) userGems.clear();
}
export function getBoostGemImage(source: unknown): string | undefined {
  if (!enabled || typeof source !== "string") return;
  return boostGems.find((gem) => source === gem.image || source.includes(gem.hash))?.image;
}
export function boostGemForBadge(badge: Record<string, unknown>): BoostGem | undefined {
  if (!enabled) return;
  if (typeof badge.layoutKey === "string" && badge.layoutKey.startsWith("byaflux:")) return;
  const ids = [badge.id, badge.badge_id, badge.legacyBadgeId, badge.key];
  if (
    ids.some(
      (id) =>
        typeof id === "string" && (/^byaflux_/.test(id) || /^byaflux-\d{17,20}-official-/.test(id)),
    )
  )
    return;
  const icons = [
    badge.iconSrc,
    badge.icon,
    badge.icon_src,
    badge.fallbackIconSrc,
    badge.simple_icon_url,
    badge.simple_icon_raster_url,
    badge.complex_icon_static_url,
  ];
  const image = icons.map(getBoostGemImage).find(Boolean);
  if (image) return boostGems.find((gem) => gem.image === image);
  for (const id of ids) {
    if (typeof id !== "string") continue;
    const tier =
      /^(?:guild_booster|guild_boosting|premium_guild_subscription|server_booster|boost)_lvl([1-9])$/i.exec(
        id,
      );
    if (tier) return boostGems[Number(tier[1]) - 1];
  }
}
export function replaceBoostGem<T extends object>(badge: T, override?: BoostGem): T {
  const gem = enabled
    ? (override ?? boostGemForBadge(badge as Record<string, unknown>))
    : undefined;
  if (!gem) return badge;
  return {
    ...badge,
    iconSrc: gem.image,
    largeIconSrc: gem.image,
    complex_icon_animated_url: gem.image,
    fallbackIconSrc: gem.image,
    ...("simple_icon_url" in badge ? { simple_icon_url: gem.image } : {}),
    ...("simple_icon_raster_url" in badge ? { simple_icon_raster_url: gem.image } : {}),
    ...("complex_icon_static_url" in badge ? { complex_icon_static_url: gem.image } : {}),
  };
}

export function getUserBoostGem(userId: string): BoostGem | undefined {
  return enabled ? userGems.get(userId) : undefined;
}
export function replaceUserBoostGems<T extends object>(userId: string, badges: T[]): T[] {
  if (!enabled) return badges;
  return badges.map((badge) => {
    const gem = boostGemForBadge(badge as Record<string, unknown>);
    if (!gem) return badge;
    if (!userGems.has(userId) && userGems.size >= 200)
      userGems.delete(userGems.keys().next().value!);
    userGems.set(userId, gem);
    return replaceBoostGem(badge, gem);
  });
}
